CREATE TABLE health_habit_definitions(id text PRIMARY KEY,subject_id text NOT NULL REFERENCES principals(id),name text NOT NULL,schedule jsonb NOT NULL,state text NOT NULL CHECK(state IN('active','paused','ended')),revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE health_goals(id text PRIMARY KEY,subject_id text NOT NULL REFERENCES principals(id),name text NOT NULL,metric_key text NOT NULL,target_value numeric(24,6) NOT NULL,unit text NOT NULL,due_on date,state text NOT NULL CHECK(state IN('active','achieved','cancelled')),revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workout_plans(id text PRIMARY KEY,subject_id text NOT NULL REFERENCES principals(id),title text NOT NULL,schedule jsonb NOT NULL,detail jsonb NOT NULL,state text NOT NULL CHECK(state IN('active','paused','ended')),revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE places(id text PRIMARY KEY,subject_id text NOT NULL REFERENCES principals(id),name text NOT NULL,address text,latitude numeric(10,7),longitude numeric(10,7),tags jsonb NOT NULL DEFAULT '[]',favorite boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),CHECK((latitude IS NULL)=(longitude IS NULL)));
CREATE INDEX places_subject_name_idx ON places(subject_id,name);
CREATE TABLE trip_day_plans(id text PRIMARY KEY,trip_id text NOT NULL REFERENCES trips(id) ON DELETE CASCADE,subject_id text NOT NULL REFERENCES principals(id),plan_date date NOT NULL,items jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,UNIQUE(trip_id,plan_date));
CREATE TABLE trip_members(trip_id text NOT NULL REFERENCES trips(id) ON DELETE CASCADE,subject_id text NOT NULL REFERENCES principals(id),role text NOT NULL CHECK(role IN('owner','editor','viewer')),visibility text NOT NULL CHECK(visibility IN('shared','private')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(trip_id,subject_id));
CREATE TABLE library_annotations(id text PRIMARY KEY,item_id text NOT NULL REFERENCES library_items(id) ON DELETE CASCADE,subject_id text NOT NULL REFERENCES principals(id),anchor jsonb NOT NULL,note text NOT NULL,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE library_derivations(id text PRIMARY KEY,item_id text NOT NULL REFERENCES library_items(id) ON DELETE CASCADE,subject_id text NOT NULL REFERENCES principals(id),source_asset_version_id text NOT NULL REFERENCES asset_versions(id),derived_asset_version_id text NOT NULL REFERENCES asset_versions(id),kind text NOT NULL,processor_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE library_proofs(id text PRIMARY KEY,item_id text NOT NULL REFERENCES library_items(id) ON DELETE CASCADE,subject_id text NOT NULL REFERENCES principals(id),revision integer NOT NULL,content_hash text NOT NULL,asset_hashes jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(item_id,revision));
ALTER TABLE library_revisions ADD COLUMN reason text;
